ary-hover-color: $blue-hover-color;\r\n\r\n// method\r\n@mixin type-primary {\r\n  color: #fff;\r\n  background-color: $primary-color;\r\n  &:hover,\r\n  &.active {\r\n    color: #fff;\r\n    background-color: $primary-hover-color;\r\n  }\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n}\r\n\r\n.#{$css-prefix} {\r\n  font-size: 13px;\r\n  line-height: normal;\r\n  user-select: none;\r\n  -moz-user-select: none;\r\n  font-family: 'Lato', 'Source Sans Pro', Roboto, Helvetica, Arial, sans-serif;\r\n  box-sizing: content-box;\r\n  background: #fff;\r\n  -webkit-font-smoothing: antialiased;\r\n\r\n  textarea {\r\n    font: 400 13px Arial, 'Lato', 'Source Sans Pro', Roboto, Helvetica,\r\n      sans-serif;\r\n  }\r\n}\r\n\r\n.#{$css-prefix}-sheet {\r\n  position: relative;\r\n  overflow: hidden;\r\n}\r\n\r\n.#{$css-prefix}-table {\r\n  // html5 bottom margin bug\r\n  vertical-align: bottom;\r\n}\r\n\r\n.#{$css-prefix}-tooltip {\r\n  font-family: inherit;\r\n  position: absolute;\r\n  padding: 5px 10px;\r\n  color: #fff;\r\n  border-radius: 1px;\r\n  background: rgba(0, 0, 0, 1);\r\n  font-size: 12px;\r\n  z-index: 201;\r\n\r\n  &:before {\r\n    pointer-events: none;\r\n    position: absolute;\r\n    left: calc(50% - 4px);\r\n    top: -4px;\r\n    content: '';\r\n    width: 8px;\r\n    height: 8px;\r\n    background: inherit;\r\n    -webkit-transform: rotate(45deg);\r\n    transform: rotate(45deg);\r\n    z-index: 1;\r\n    box-shadow: 1px 1px 3px -1px rgba(0, 0, 0, 0.3);\r\n  }\r\n}\r\n\r\n.#{$css-prefix}-color-palette {\r\n  padding: 5px;\r\n\r\n  table {\r\n    margin: 0;\r\n    padding: 0;\r\n    border-collapse: separate;\r\n    border-spacing: 2;\r\n    background: #fff;\r\n\r\n    td {\r\n      margin: 0;\r\n      cursor: pointer;\r\n      border: 1px solid transparent;\r\n\r\n      &:hover {\r\n        border-color: #ddd;\r\n      }\r\n\r\n      .#{$css-prefix}-color-palette-cell {\r\n        width: 16px;\r\n        height: 16px;\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.#{$css-prefix}-border-palette {\r\n  padding: 6px;\r\n\r\n  table {\r\n    margin: 0;\r\n    padding: 0;\r\n    border-collapse: separate;\r\n    border-spacing: 0;\r\n    background: #fff;\r\n    table-layout: fixed;\r\n\r\n    td {\r\n      margin: 0;\r\n    }\r\n  }\r\n\r\n  .#{$css-prefix}-border-palette-left {\r\n    border-right: 1px solid #eee;\r\n    padding-right: 6px;\r\n\r\n    .#{$css-prefix}-border-palette-cell {\r\n      width: 30px;\r\n      height: 30px;\r\n      cursor: pointer;\r\n      text-align: center;\r\n\r\n      .#{$css-prefix}-icon-img {\r\n        opacity: 0.8;\r\n      }\r\n\r\n      &:hover {\r\n        background-color: #eee;\r\n      }\r\n    }\r\n  }\r\n\r\n  .#{$css-prefix}-border-palette-right {\r\n    padding-left: 6px;\r\n\r\n    .#{$css-prefix}-toolbar-btn {\r\n      margin-top: 0;\r\n      margin-bottom: 3px;\r\n    }\r\n\r\n    .#{$css-prefix}-line-type {\r\n      position: relative;\r\n      left: 0;\r\n      top: -3px;\r\n    }\r\n  }\r\n}\r\n\r\n.#{$css-prefix}-dropdown {\r\n  position: relative;\r\n\r\n  .#{$css-prefix}-dropdown-content {\r\n    position: absolute;\r\n    z-index: 200;\r\n    background: #fff;\r\n    box-shadow: 1px 2px 5px 2px rgba(51, 51, 51, 0.15);\r\n  }\r\n\r\n  &.bottom-left {\r\n    .#{$css-prefix}-dropdown-content {\r\n      top: calc(100% + 5px);\r\n      left: 0;\r\n    }\r\n  }\r\n\r\n  &.bottom-right {\r\n    .#{$css-prefix}-dropdown-content {\r\n      top: calc(100% + 5px);\r\n      right: 0;\r\n    }\r\n  }\r\n\r\n  &.top-left {\r\n    .#{$css-prefix}-dropdown-content {\r\n      bottom: calc(100% + 5px);\r\n      left: 0;\r\n    }\r\n  }\r\n\r\n  &.top-right {\r\n    .#{$css-prefix}-dropdown-content {\r\n      bottom: calc(100% + 5px);\r\n      right: 0;\r\n    }\r\n  }\r\n\r\n  .#{$css-prefix}-dropdown-title {\r\n    padding: 0 5px;\r\n    display: inline-block;\r\n  }\r\n\r\n  .#{$css-prefix}-dropdown-header {\r\n    .#{$css-prefix}-icon.arrow-left {\r\n      margin-left: 4px;\r\n    }\r\n    .#{$css-prefix}-icon.arrow-right {\r\n      width: 10px;\r\n      margin-right: 4px;\r\n      .arrow-down {\r\n        left: -130px;\r\n      }\r\n    }\r\n  }\r\n}\r\n/* resizer **/\r\n.#{$css-prefix}-resizer {\r\n  position: absolute;\r\n  z-index: 11;\r\n\r\n  .#{$css-prefix}-resizer-hover {\r\n    background-color: rgba(75, 137, 255, 0.25);\r\n  }\r\n  .#{$css-prefix}-resizer-line {\r\n    position: absolute;\r\n  }\r\n\r\n  &.horizontal {\r\n    cursor: row-resize;\r\n    .#{$css-prefix}-resizer-line {\r\n      border-bottom: 2px dashed rgb(75, 137, 255);\r\n      left: 0;\r\n      bottom: 0;\r\n    }\r\n  }\r\n  &.vertical {\r\n    cursor: col-resize;\r\n    .#{$css-prefix}-resizer-line {\r\n      border-right: 2px dashed rgb(75, 137, 255);\r\n      top: 0;\r\n      right: 0;\r\n    }\r\n  }\r\n}\r\n/* scrollbar */\r\n.#{$css-prefix}-scrollbar {\r\n  position: absolute;\r\n  bottom: 0;\r\n  right: 0;\r\n  background-color: #f4f5f8;\r\n  opacity: 0.9;\r\n  z-index: 12;\r\n  &.horizontal {\r\n    right: 15px;\r\n    overflow-x: scroll;\r\n    overflow-y: hidden;\r\n    > div {\r\n      height: 1px;\r\n      background: #ddd;\r\n    }\r\n  }\r\n  &.vertical {\r\n    bottom: 15px;\r\n    overflow-x: hidden;\r\n    overflow-y: scroll;\r\n    > div {\r\n      width: 1px;\r\n      background: #ddd;\r\n    }\r\n  }\r\n  &:hover {\r\n    // opacity: .85;\r\n  }\r\n}\r\n\r\n/* #{$css-prefix}-overlayer */\r\n.#{$css-prefix}-overlayer {\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  z-index: 10;\r\n  .#{$css-prefix}-overlayer-content {\r\n    position: absolute;\r\n    overflow: hidden;\r\n    pointer-events: none;\r\n    width: 100%;\r\n    height: 100%;\r\n  }\r\n}\r\n\r\n.#{$css-prefix}-editor,\r\n.#{$css-prefix}-selector {\r\n  box-sizing: content-box;\r\n  position: absolute;\r\n  overflow: hidden;\r\n  pointer-events: none;\r\n  top: 0;\r\n  left: 0;\r\n  width: 100%;\r\n  height: 100%;\r\n}\r\n\r\n/* #{$css-prefix}-selector */\r\n.#{$css-prefix}-selector {\r